import {groups} from './registry.js';
import {helpers,escape,href} from './shared/helpers.js';
import {parseRoute} from './shared/router.js';
import {createScope,mountArtist,destroyArtist} from './shared/lifecycle.js';
import {createTransitionGate} from './shared/transition.js';

function loadStyle(document,slug,signal){
  return new Promise((resolve,reject)=>{
    const link=document.createElement('link');link.rel='stylesheet';link.href=`groups/${slug}/styles.css`;
    const done=()=>{link.onload=null;link.onerror=null;signal.removeEventListener('abort',abort);};
    const abort=()=>{done();link.remove();reject(new DOMException('Artist transition cancelled','AbortError'));};
    link.onload=()=>{done();resolve(link);};link.onerror=()=>{done();link.remove();reject(new Error('Group stylesheet could not be loaded'));};
    if(signal.aborted){abort();return;}signal.addEventListener('abort',abort,{once:true});document.head.append(link);
  });
}
export function createArtistHost({document,window,root=document.getElementById('artist-root'),status=document.getElementById('host-status'),loadModule=slug=>import(`./groups/${slug}/index.js`),styleLoader=loadStyle}){
  const host=createScope({id:'artist-host',scheduler:window}),gate=createTransitionGate(),focusedByRoute=new Map();
  const directory=()=>`<section class="host-panel"><h1>团体独立页面</h1><p>选择团体，浏览成员、作品与时间轴。</p><ul class="host-directory">${groups.map(group=>`<li><a href="${href(group.slug)}"><span>${escape(group.name)}</span><span aria-hidden="true">↗</span></a></li>`).join('')}</ul></section>`;
  async function render(){
    const transition=gate.begin();destroyArtist(root);status.textContent='';
    const route=parseRoute(window.location.hash);
    if(!route.slug){delete root.dataset.artist;root.innerHTML=directory();document.title='团体独立页面';return;}
    const entry=groups.find(group=>group.slug===route.slug);
    if(!entry||route.page==='not-found'){delete root.dataset.artist;root.innerHTML='<section class="host-panel"><h1>找不到这个页面</h1><a href="#/">返回团体目录</a></section>';return;}
    let style=null;
    try{
      const module=await loadModule(entry.slug);if(!transition.isCurrent())return;
      if(module.artist?.slug!==entry.slug)throw new Error('Group module identity mismatch');
      style=await styleLoader(document,entry.slug,transition.signal);if(!transition.isCurrent()){style.remove();return;}
      const handle=mountArtist({root,module,route,helpers,scheduler:window,
        onIdentityError:()=>{status.textContent='无法打开这项内容，请返回目录重试。';},
        onActivation:({element,identity})=>{const target=element.getAttribute('href');if(target)focusedByRoute.set(identity.returnRoute,target);}
      });
      handle.scope.own(style);style=null;
      handle.scope.on(transition.signal,'abort',()=>handle.destroy(),{once:true});
      const result=await handle.ready;if(!transition.isCurrent()||result.status!=='mounted')return;
      document.title=`${module.artist.name} · ${({home:'首页',members:'成员',member:'成员详情',works:'作品',work:'作品详情',timeline:'时间轴'})[route.page]}`;
      const prior=focusedByRoute.get(href(route.slug,route.page,route.key,route.query));
      const match=prior?[...root.querySelectorAll('a[href]')].find(anchor=>anchor.getAttribute('href')===prior):null;
      if(match)match.focus({preventScroll:true});else{window.scrollTo({top:0,behavior:'instant'});root.focus({preventScroll:true});}
    }catch(error){
      style?.remove();if(!transition.isCurrent()||error.name==='AbortError')return;
      destroyArtist(root);delete root.dataset.artist;
      root.innerHTML=`<section class="host-panel"><h1>${escape(entry.name)}</h1><div class="host-error"><p>此团页面暂时无法载入。</p><p class="host-code">${escape(error.message)}</p></div><p><a href="#/">返回团体目录</a></p></section>`;
      console.error(`[artist:${entry.slug}]`,error);
    }
  }
  host.on(root,'error',event=>{if(event.target?.tagName==='IMG'){event.target.classList.add('media-failed');event.target.setAttribute('aria-label',`${event.target.alt}（图片载入失败）`);}},true);
  const skip=document.querySelector('.host-skip');if(skip)host.on(skip,'click',event=>{event.preventDefault();root.focus();root.scrollIntoView();});
  host.on(window,'hashchange',()=>{if(window.location.hash.startsWith('#/')||!window.location.hash)render();});
  return {render,destroy(){gate.destroy();destroyArtist(root);host.destroy();},scope:host};
}
if(typeof document!=='undefined'&&typeof window!=='undefined'){
  const host=createArtistHost({document,window});host.render();
}

