import data from './data.js';
import payload from './reconciliation.js';
import {reconcileArtist} from '../../shared/reconcile.js';
import {summaries} from './public-copy.js';
import {relatedVideoWorks} from './video-relations.js';
import {renderMemberFacts,renderEventBody,renderMemberSources} from './public-content.js';

const asset=key=>data.assets.find(a=>a.key===key);
const eventDate=value=>String(value||'').match(/\d{4}(?:[.\-]\d{2}){0,2}/)?.[0].replaceAll('.','-')||null;
const movie=({work,kind})=>({id:kind==='mv'?work.id:null,...(kind==='stage'?{candidateKey:`video:${work.id}:stage:${work.stage.id}`} : {}),workId:work.id,title:work.canonicalTitle||work.title,displayTitle:work.title,sourceTitle:work.sourceTitle,publicBaseline:work.publicBaseline,type:kind,version:kind==='mv'?(work.canonicalVersion||work.version):work.stage.kind,date:kind==='mv'?work.date:work.stage.date,dateKind:kind==='mv'?'work-date':'video-publication-date',videoId:work[kind].id,sourceUrl:work[kind].url,sources:[work[kind].url],channel:work[kind].channel,image:asset(work[kind].key),imageKey:work[kind].key,projectReleaseId:null});
const baseArtist={slug:'billlie',id:data.groupId,name:'Billlie',members:data.members.map(m=>({...m,name:m.stage,nameZh:m.cn,image:asset(m.id)})),works:[...data.releases.map(r=>({...r,id:null,candidateKey:r.id,type:'release',dateKind:'release-date',projectReleaseId:r.projectReleaseId,sources:[r.source],image:asset(r.id)})),...data.works.flatMap(work=>[movie({work,kind:'mv'}),...(work.stage?[movie({work,kind:'stage'})]:[])])],timeline:data.events.map(e=>({...e,id:null,candidateKey:e.id,title:e.text.split(' · ')[0],date:eventDate(e.date),dateKind:e.date.includes('公告')?'announcement-date':'event-date',precision:eventDate(e.date)?.length===10?'day':eventDate(e.date)?.length===7?'month':'year',sources:e.sources})),assets:data.assets};
const reconciled=reconcileArtist(baseArtist,payload);
export const artist={...reconciled,timeline:reconciled.timeline.map(event=>({...event,publicSummary:summaries[event.id]??event.summary}))};


export function render({route,helpers:H}) {
  const e=H.escape,key=H.entityKey;
  const workContext=['works','work'].includes(route.page)?route.query:new URLSearchParams();
  const groupHref=(page='home',id=null,query)=>H.href('billlie',page,id,query??(page==='work'||page==='works'&&route.page==='work'?workContext:{}));
  const queryWith=patch=>{const q=new URLSearchParams(route.query);for(const [k,v]of Object.entries(patch))q.set(k,v);return q;};
  const memberName=m=>m.nameZh||m.cn||m.name;
  const link=(label,page='home',id=null,cls='')=>`<a class="bl-button ${cls}" href="${e(groupHref(page,id))}">${e(label)}</a>`;
  const picture=(a,alt,cls='',eager=false)=>a?H.image(a,alt,{className:cls,loading:eager?'eager':'lazy',fit:'contain'}):'';
  const dateLine=w=>w.date?`<p class="bl-meta">${e(({release:'发行日',mv:'作品日期',stage:'舞台公开日'})[w.type])} · <time datetime="${e(w.date)}">${e(H.dateLabel(w.date))}</time></p>`:'';
  const title=(en,cn)=>`<div class="bl-title"><h1>${e(en)}</h1><p>${e(cn)}</p></div>`;
  const heading=(en,cn)=>`<div class="bl-heading"><h2>${e(en)}</h2><p>${e(cn)}</p></div>`;
  const memberCard=m=>`<article class="bl-member"><a href="${e(groupHref('member',key(m)))}">${picture(m.image,`${memberName(m)} ${m.stage}`,'bl-portrait')}<h3>${e(memberName(m))}</h3></a><p>${e(m.stage)}</p></article>`;
  const releaseCard=r=>`<article class="bl-record"><a href="${e(groupHref('work',key(r)))}">${picture(r.image,r.title+' 发行封面','bl-cover')}<h3>${e(r.title)}</h3></a><p class="bl-meta">${e(r.kind)} · ${e(r.date)}</p>${link('发行详情','work',key(r))}</article>`;
  const filmCard=w=>`<article class="bl-film"><a href="${e(groupHref('work',key(w)))}">${picture(w.image,w.title+' '+(w.type==='stage'?'舞台':'MV')+'预览','bl-video')}<h3>${e(w.title)}</h3></a><p class="bl-video-type">${w.type==='stage'?'舞台 / LIVE PERFORMANCE':'MV / MUSIC VIDEO'}</p><p class="bl-meta">${e(w.version||'')}</p>${dateLine(w)}${link(w.type==='stage'?'舞台详情':'MV详情','work',key(w))}</article>`;
  const releases=artist.works.filter(w=>w.type==='release'),mvs=artist.works.filter(w=>w.type==='mv'),latest=releases.find(r=>r.candidateKey===data.latestReleaseId)||releases[0];
  const active=route.page==='member'?'members':route.page==='work'?'works':route.page;
  const header=`<header class="bl-header"><a class="bl-brand" href="${e(groupHref())}">Billlie</a><nav aria-label="Billlie 主要导航">${[['首页','home'],['成员','members'],['作品','works'],['时间轴','timeline']].map(([name,page])=>`<a href="${e(groupHref(page))}" ${active===page?'aria-current="page"':''}>${name}</a>`).join('')}</nav></header>`;
  let content='';
  if(route.page==='home')content=`<section class="bl-lead bl-wrap"><div class="bl-lead-copy"><h1>BILLLIE</h1><p class="bl-meta">${e(latest.kind)} · ${e(latest.date)}</p><h2>${e(latest.title)}</h2>${link('阅读发行','work',key(latest),'bl-primary')}</div><a class="bl-lead-cover" href="${e(groupHref('work',key(latest)))}">${picture(latest.image,latest.title+' 发行封面','bl-cover',true)}</a></section><section class="bl-cast-band"><div class="bl-wrap">${heading('Members','成员')}<div class="bl-cast-grid">${artist.members.map(memberCard).join('')}</div>${link('成员与经历','members')}</div></section><section class="bl-wrap bl-section">${heading('Releases','音乐发行')}<div class="bl-release-grid bl-selected">${releases.slice(0,3).map(releaseCard).join('')}</div>${link('全部作品','works')}</section><section class="bl-film-band"><div class="bl-wrap">${heading('In motion','音乐影像')}<div class="bl-film-grid">${mvs.slice(-2).reverse().map(filmCard).join('')}</div></div></section><section class="bl-wrap bl-closing"><h2>Timeline</h2>${link('从最初开始 · 时间轴','timeline')}</section>`;
  if(route.page==='members')content=`<section class="bl-wrap bl-section">${title('Members','成员')}<div class="bl-cast-grid bl-directory">${artist.members.map(memberCard).join('')}</div><div class="bl-members-history"><h2>从六人出发，走向七人的篇章。</h2><p>Billlie 于2021年11月10日以六人阵容出道，随后于11月19日公布金秀娟（SHEON）加入。</p>${link('浏览团体时间轴','timeline')}</div></section>`;
  if(route.page==='member'){
    const m=artist.members.find(m=>key(m)===route.key);
    if(m){const i=artist.members.indexOf(m),next=artist.members[(i+1)%artist.members.length];content=`<section class="bl-wrap bl-section" data-member-id="${e(m.id)}">${link('返回成员目录','members')}<div class="bl-person-spread">${picture(m.image,m.cn+' '+m.stage,'bl-person-photo',true)}<div class="bl-person-copy"><p class="bl-meta">Billlie</p><h1>${e(memberName(m))}</h1><p class="bl-stage-name">${e(m.stage)}</p>${m.profile?`<p class="bl-biography">${e(m.profile)}</p>`:''}${renderMemberFacts(m,H)}<details class="bl-sources"><summary>成员资料来源</summary>${renderMemberSources(m,H)}</details>${link('浏览团体作品','works')}${link('下一位 · '+next.cn,'member',key(next))}</div></div></section>`;}
  }
  if(route.page==='works'){
    const type=route.query.get('type')||'all',q=route.query.get('q')||'',items=H.filterWorks(artist.works,{query:q,type});
    content=`<section class="bl-wrap bl-section">${title('Works','作品库')}<div class="bl-catalog-tools"><nav aria-label="作品类型">${[['all','全部'],['release','发行'],['mv','MV'],['stage','舞台']].map(([value,label])=>`<a href="${e(groupHref('works',null,queryWith({type:value,q})))}" ${type===value?'aria-current="page"':''}>${label}</a>`).join('')}</nav><form data-billlie-search><label for="billlie-query">搜索作品</label><div><input id="billlie-query" name="q" type="search" value="${e(q)}" placeholder="作品名"><button type="submit">搜索</button></div></form></div><p class="bl-count" role="status">${items.length} 项作品</p>${['release','mv','stage'].map(t=>{const list=items.filter(w=>w.type===t);return list.length?`<section class="bl-catalog-section">${heading(({release:'Releases',mv:'Music videos',stage:'Live performances'})[t],({release:'发行',mv:'MV',stage:'舞台'})[t])}<div class="${t==='release'?'bl-release-grid':'bl-film-grid'}">${list.map(t==='release'?releaseCard:filmCard).join('')}</div></section>`:'';}).join('')}${!items.length?`<div class="bl-empty"><h2>没有找到符合条件的作品</h2>${link('查看全部作品','works')}</div>`:''}</section>`;
  }
  if(route.page==='work'){
    const w=artist.works.find(w=>key(w)===route.key);
    if(w)content=w.type==='release'?`<section class="bl-wrap bl-section" data-work-key="${e(key(w))}">${link('返回作品库','works')}<div class="bl-release-spread">${picture(w.image,w.title+' 发行封面','bl-cover',true)}<div><p class="bl-meta">${e(w.kind)}</p><h1>${e(w.title)}</h1><p>${e(w.artistCredit||'Billlie')}</p>${dateLine(w)}<p>${e(w.tracks)} 首歌曲</p>${H.sources(w.sources)}</div></div><section class="bl-section">${heading('More chapters','其他发行')}<div class="bl-release-grid bl-selected">${releases.filter(x=>key(x)!==key(w)).slice(0,3).map(releaseCard).join('')}</div></section></section>`:`<section class="bl-wrap bl-section" data-work-key="${e(key(w))}">${link('返回作品库','works')}${title(w.title,w.type==='stage'?'舞台与现场':'音乐影像')}<div class="bl-cinema">${picture(w.image,w.title+' '+(w.type==='stage'?'舞台':'MV')+'预览','bl-video',true)}</div><div class="bl-video-information"><p>${e(w.version||'')}</p><p class="bl-meta">发布频道 · ${e(w.channel||'')}</p>${dateLine(w)}${H.sources(w.sources)}</div><section class="bl-section">${heading('Another view','同一作品的另一种观看')}<div class="bl-film-grid">${relatedVideoWorks(w,artist.works).map(filmCard).join('')}</div></section></section>`;
  }
  if(route.page==='timeline'){
    const dated=H.sortTimeline(artist.timeline.filter(event=>event.date)),undated=artist.timeline.filter(event=>!event.date);
