import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {helpers as H} from '../../shared/helpers.js';

const sourceRoot=new URL('../../inputs/reconciliation/',import.meta.url);
const read=name=>JSON.parse(fs.readFileSync(new URL(name,sourceRoot),'utf8'));
const publicMembers=read('members-public-baseline.json').members;
const careers=read('member-career-periods.json');
const modules=await Promise.all(['billlie','katseye','vcha'].map(async slug=>({slug,...await import(`../${slug}/index.js`)})));
const route=(slug,page,key=null,query=new URLSearchParams())=>({slug,page,key,query});
const decode=value=>value.replaceAll('&amp;','&').replaceAll('&quot;','"').replaceAll('&#39;',"'").replaceAll('&lt;','<').replaceAll('&gt;','>');
const anchors=html=>[...html.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/g)].map(match=>({attributes:match[1],href:decode(/href="([^"]*)"/.exec(match[1])?.[1]??''),text:decode(match[2].replace(/<[^>]+>/g,''))}));

for(const module of modules){
 const {slug,artist,render}=module;
 const {relatedVideoWorks}=await import(`../${slug}/video-relations.js`);
 const originalTimeline=read(`artist-timelines/${slug}.json`);
 const originalMembers=publicMembers.filter(m=>m.currentGroupIds.includes(artist.id)||m.formerGroupIds.includes(artist.id));

 test(`${slug}: complete public member rows and original career periods survive`,()=>{
  assert.equal(artist.members.length,originalMembers.length);
  for(const original of originalMembers){
   const member=artist.members.find(m=>m.id===original.memberId);
   assert(member,original.memberId);
   assert.deepEqual(member.publicBaseline,original);
   assert.deepEqual(member.currentGroupIds,original.currentGroupIds);
   assert.deepEqual(member.formerGroupIds,original.formerGroupIds);
   for(const field of ['role','status','officialUrl'])if(original[field])assert.equal(member[field],original[field]);
   if(original.profile&&!original.profileExcerptOnly)assert.equal(member.profile,original.profile);
   const expectedPeriods=careers.periods.filter(p=>p.memberId===member.id&&p.groupId===artist.id);
   assert.deepEqual(member.careerPeriods,expectedPeriods);
   const ids=new Set(expectedPeriods.flatMap(p=>p.sourceIds));
   assert.deepEqual(member.careerSources,careers.sources.filter(s=>ids.has(s.sourceId)));
  }
 });

 test(`${slug}: every individual biography, role and sourced career record is rendered`,()=>{
  for(const member of artist.members){
   const html=render({route:route(slug,'member',member.id),helpers:H});
   assert(html.includes(`data-member-id="${H.escape(member.id)}"`));
   assert(html.includes(H.escape(member.profile)),`${member.id} biography`);
   if(member.role)assert(html.includes(H.escape(member.role)),`${member.id} role`);
   if(member.status)assert(html.includes(H.escape(member.status)),`${member.id} status`);
   for(const period of member.careerPeriods){
    assert(html.includes(`data-period-id="${H.escape(period.periodId)}"`));
    if(period.startDate)assert(html.includes(`datetime="${period.startDate}"`));
    if(period.endDate)assert(html.includes(`datetime="${period.endDate}"`));
    if(period.announcedDate?.value)assert(html.includes(`datetime="${period.announcedDate.value}"`));
    if(period.effectiveDate?.value)assert(html.includes(`datetime="${period.effectiveDate.value}"`));
    for(const event of period.events??[])assert(html.includes(H.escape(event.label)));
   }
   for(const source of member.careerSources)assert(html.includes(H.escape(source.url)),source.url);
   assert(!html.includes('needs_relation'));
   assert(!html.includes('至今'),'an unknown period end must not become present membership');
  }
 });

 test(`${slug}: exact canonical ready event rows, IDs and all date semantics survive`,()=>{
  assert.deepEqual(artist.sourceTimeline,originalTimeline.events);
  const ready=originalTimeline.events.filter(event=>event.reviewStatus==='ready');
  assert.deepEqual(artist.timeline.map(event=>event.id),ready.map(event=>event.id));
  for(const original of ready){
   const event=artist.timeline.find(event=>event.id===original.id);
   assert.deepEqual(event.canonicalEvent,original);
   for(const field of ['title','summary','eventDate','announcementDate','plannedDate','sources','memberIds','workIds','status','reviewStatus'])assert.deepEqual(event[field],original[field],`${original.id} ${field}`);
   const axis=original.eventDate??original.announcementDate;
   assert.equal(event.date,axis?.value??null);
   assert.equal(event.precision,axis?.precision??null);
  }
 });

 test(`${slug}: dated axis and undated notices expose every original event once without review copy`,()=>{
  const html=render({route:route(slug,'timeline'),helpers:H});
  assert.equal((html.match(/data-timeline/g)||[]).length,1);
  for(const event of artist.timeline){
   assert.equal(html.split(`data-event-id="${event.id}"`).length-1,1,event.id);
   assert(html.includes(H.escape(event.title)),event.title);
   assert(html.includes(H.escape(event.publicSummary)),event.id+' public summary');
   for(const source of event.sources)assert(html.includes(H.escape(source.url)),source.url);
  }
  assert(!/(needs_relation|L231|旧e-vcha|不另造重复首发节点|核验台账)/.test(html));
  const dateRows=[...html.matchAll(/<li data-event-id="([^"]+)"><time datetime="([^"]+)">/g)];
  assert.deepEqual(dateRows.map(row=>row[1]),H.sortTimeline(artist.timeline.filter(event=>event.date)).map(event=>event.id));
 });

 test(`${slug}: filtered release/MV/stage detail and explicit back preserve the exact same-group query`,()=>{
  for(const type of ['release','mv','stage']){
   const work=artist.works.find(work=>work.type===type);assert(work);
   const query=new URLSearchParams([['type',type],['q',work.title],['sort','oldest'],['tag','one'],['tag','two']]);
   if(slug==='vcha')query.set('chapter',work.chapter);
   const html=render({route:route(slug,'works',null,query),helpers:H});
   const prefix=H.href(slug,'work',H.entityKey(work));
   const entry=anchors(html).find(anchor=>anchor.href.split('?')[0]===prefix);assert(entry,prefix);
   const detailQuery=new URLSearchParams(entry.href.split('?')[1]??'');
   assert.equal(detailQuery.toString(),query.toString());
   const detail=render({route:route(slug,'work',H.entityKey(work),detailQuery),helpers:H});
   assert(detail.includes(`data-work-key="${H.escape(H.entityKey(work))}"`));
   const back=anchors(detail).find(anchor=>/返回作品库|← .*目录/.test(anchor.text));assert(back,'explicit catalogue back control');
   assert.equal(back.href,H.href(slug,'works',null,query));
  }
  const work=artist.works[0],html=render({route:route(slug,'work',H.entityKey(work)),helpers:H});
  const back=anchors(html).find(anchor=>/返回作品库|← .*目录/.test(anchor.text));
  assert.equal(back.href,H.href(slug,'works'),'an empty all-works query must not become a type filter');
 });

 test(`${slug}: only exact production parent IDs connect MV and stage; release/candidate/empty keys never connect`,()=>{
  const mv={id:'recActualMV',type:'mv',title:'same title',date:'2024-01-01',videoId:'same-video'};
  const linkedFields=[{parentWorkId:mv.id},{workId:mv.id},{sourceWorkId:mv.id},{parentWorkIds:['recOtherMV',mv.id]}];
  for(const fields of linkedFields){
   const stage={id:'recStageEntity',type:'stage',...fields};
   assert.deepEqual(relatedVideoWorks(mv,[mv,stage]),[stage]);
   assert.deepEqual(relatedVideoWorks(stage,[mv,stage]),[mv]);
  }
  const unboundMV={type:'mv',candidateKey:'candidate:same',title:mv.title,date:mv.date,videoId:mv.videoId};
  const unboundStage={type:'stage',candidateKey:'candidate:same',title:mv.title,date:mv.date,videoId:mv.videoId};
  const mismatches=[
   {type:'stage'},
   {...unboundStage},
   {type:'stage',id:mv.id}, // A stage entity ID is not its parent work ID.
   {type:'stage',workId:'recDifferentMV',title:mv.title,date:mv.date,videoId:mv.videoId},
   {type:'stage',workId:'',parentWorkId:' ',sourceWorkId:null,parentWorkIds:[undefined,'']},
   {type:'stage',workId:'candidate:same'},
   {type:'release',workId:mv.id}
  ];
  assert.deepEqual(relatedVideoWorks(mv,mismatches),[]);
  assert.deepEqual(relatedVideoWorks(unboundMV,[unboundStage,...mismatches]),[]);
  assert.deepEqual(relatedVideoWorks({...mv,id:'candidate:same'},[{type:'stage',parentWorkId:'candidate:same'}]),[]);
  assert.deepEqual(relatedVideoWorks({type:'release',workId:mv.id},[mv,...mismatches]),[]);
  assert.deepEqual(relatedVideoWorks({type:'mv',id:'recOne'},[{type:'mv',id:'recOne'}]),[]);
 });

 test(`${slug}: every existing stage/MV pair retains its own exact counterpart and group query`,()=>{
  const before=JSON.stringify(artist.works),stages=artist.works.filter(work=>work.type==='stage');
  assert.equal(stages.length,({billlie:13,katseye:7,vcha:4})[slug]);
  const query=new URLSearchParams([['type','stage'],['q','original query'],['tag','one'],['tag','two']]);
  for(const stage of stages){
   const mv=artist.works.find(work=>work.type==='mv'&&work.id===stage.workId);assert(mv,stage.workId);
   assert.deepEqual(relatedVideoWorks(stage,artist.works),[mv]);
   assert(relatedVideoWorks(mv,artist.works).includes(stage));
   for(const [from,to] of [[stage,mv],[mv,stage]]){
    const html=render({route:route(slug,'work',H.entityKey(from),query),helpers:H});
    const counterpart=anchors(html).find(anchor=>anchor.href===H.href(slug,'work',H.entityKey(to),query));
    assert(counterpart,`${H.entityKey(from)} -> ${H.entityKey(to)}`);
   }
  }
  for(const release of artist.works.filter(work=>work.type==='release')){
   assert.deepEqual(relatedVideoWorks(release,artist.works),[]);
   const html=render({route:route(slug,'work',H.entityKey(release)),helpers:H});
   assert(!/查看同作品|阅读同作品|同一作品的另一种观看/.test(html),'release cannot borrow a video relation');
  }
  assert.equal(JSON.stringify(artist.works),before,'counterpart selection must not mutate work data');
 });

 test(`${slug}: actual detail rendering cannot borrow an unbound video or release relation`,()=>{
  const before=JSON.stringify(artist.works),length=artist.works.length;
  const seed=artist.works.find(work=>work.type==='mv');
  const unboundMV={...seed,id:null,workId:undefined,candidateKey:'test-only:unbound-mv',title:'Test-only unbound video'};
  const unboundStage={...seed,id:null,workId:undefined,candidateKey:'test-only:unbound-stage',type:'stage',title:unboundMV.title};
  const release=artist.works.find(work=>work.type==='release');
  try{
   artist.works.push(unboundMV,unboundStage);
   for(const work of [unboundMV,unboundStage,release]){
    const html=render({route:route(slug,'work',H.entityKey(work)),helpers:H});
    const links=anchors(html);
    for(const forbidden of [unboundMV,unboundStage])assert(!links.some(anchor=>anchor.href===H.href(slug,'work',H.entityKey(forbidden))),'unbound entity must not become another version');
    assert(!/查看同作品|阅读同作品/.test(html),'release and unbound video have no claimed counterpart');
   }
  }finally{artist.works.splice(length);}
  assert.equal(JSON.stringify(artist.works),before,'test-only fixtures are removed');
 });

 test(`${slug}: search-submit handler retains unrelated and repeated query parameters`,()=>{
  const previousFormData=globalThis.FormData,previousLocation=globalThis.location;
  const listeners=new Map(),values={q:'中文 & query',type:'stage',chapter:'girlset'};
  const form={addEventListener:(name,callback)=>listeners.set(name,callback),removeEventListener:(name,callback)=>{if(listeners.get(name)===callback)listeners.delete(name);}};
  const root={querySelector:selector=>selector.includes('search')?form:null};
  const query=new URLSearchParams([['q','before'],['type','stage'],['sort','oldest'],['tag','one'],['tag','two']]);
  if(slug==='vcha')query.set('chapter','girlset');
  try{
   globalThis.FormData=class {get(name){return values[name];}};
   globalThis.location={hash:''};
   const cleanup=module.afterRender({root,route:route(slug,'works',null,query),helpers:H});
   assert(listeners.has('submit'));listeners.get('submit')({preventDefault(){}});
   const result=new URL(globalThis.location.hash.replace(/^#/,''),'https://preview.invalid');
   assert.equal(result.pathname,`/${slug}/works`);
   assert.equal(result.searchParams.get('q'),values.q);
   assert.equal(result.searchParams.get('type'),'stage');
   assert.equal(result.searchParams.get('sort'),'oldest');
   assert.deepEqual(result.searchParams.getAll('tag'),['one','two']);
   if(slug==='vcha')assert.equal(result.searchParams.get('chapter'),'girlset');
   cleanup();assert(!listeners.has('submit'));
  }finally{
   globalThis.FormData=previousFormData;
   if(previousLocation===undefined)delete globalThis.location;else globalThis.location=previousLocation;
  }
 });
}

